module uart_top
   (clock,
    nreset,
    sdata_rx_in,
    valid_rx_in,
    ready_rx_out,
    data_rx_out,
    valid_tx_in,
    data_tx_in,
    ready_tx_out,
    sdata_tx_out);
  input clock;
  input nreset;
  input sdata_rx_in;
  input valid_rx_in;
  output ready_rx_out;
  output [7:0]data_rx_out;
  input valid_tx_in;
  input [7:0]data_tx_in;
  output ready_tx_out;
  output sdata_tx_out;

  wire clock;
  wire [7:0]data_rx_out;
  wire [7:0]data_tx_in;
  wire nreset;
  wire ready_rx_out;
  wire sdata_rx_in;
  wire sdata_tx_out;
  wire uart_receiver_n_0;
  wire valid_tx_in;

  uart_rx uart_receiver
       (.SystolicCore0_i_1(uart_receiver_n_0),
        .clock(clock),
        .data_rx_out(data_rx_out),
        .nreset(nreset),
        .ready_rx_out(ready_rx_out),
        .sdata_rx_in(sdata_rx_in));
  uart_tx uart_transmitter
       (.clock(clock),
        .\counter_reg[2] (uart_receiver_n_0),
        .data_tx_in(data_tx_in[3:0]),
        .sdata_tx_out(sdata_tx_out),
        .valid_tx_in(valid_tx_in));
endmodule

